#!/usr/bin/env node
/* DS-01 — DTCG single source -> CSS custom properties + TS constants.
 * Run: npm run tokens:build  (from apps/web). Generated files: DO NOT EDIT. */
import StyleDictionary from 'style-dictionary';

const SEL = { light: ':root:not(.dark)', dark: ':root.dark', density: "[data-density='compact']" };

const cssFormat = ({ dictionary }) => {
  const groups = { light: [], dark: [], density: [] };
  for (const t of dictionary.allTokens) {
    const [group, ...rest] = t.path;
    groups[group]?.push([rest.join('-'), t.$value ?? t.value]);
  }
  const block = (sel, decls) =>
    `${sel} {\n${decls.map(([n, v]) => `  --${n}: ${v};`).join('\n')}\n}`;
  return (
    '/* GENERATED by design-tokens/sd.config.mjs from design-tokens/tokens.json (DS-01). */\n' +
    '/* Do not edit — change the JSON source and rebuild. */\n\n' +
    [
      block(SEL.light, groups.light),
      block(SEL.dark, groups.dark),
      block(SEL.density, groups.density),
    ].join('\n\n') +
    '\n'
  );
};

const tsFormat = ({ dictionary }) => {
  const groups = { light: {}, dark: {}, density: {} };
  for (const t of dictionary.allTokens) {
    const [group, ...rest] = t.path;
    if (groups[group]) groups[group][rest.join('-')] = t.$value ?? t.value;
  }
  return (
    '/* GENERATED by design-tokens/sd.config.mjs (DS-01). Do not edit. */\n' +
    'export const designTokens = ' +
    JSON.stringify(groups, null, 2) +
    ' as const;\n\n' +
    'export type DesignTokens = typeof designTokens;\n'
  );
};

const sd = new StyleDictionary({
  source: ['design-tokens/tokens.json'],
  hooks: { formats: { 'vimad/themes': cssFormat, 'vimad/ts': tsFormat } },
  platforms: {
    web: {
      files: [
        { destination: 'src/styles/generated/themes.css', format: 'vimad/themes' },
        { destination: 'src/styles/generated/tokens.ts', format: 'vimad/ts' },
      ],
    },
  },
});
await sd.buildAllPlatforms();
console.log('tokens built -> src/styles/generated/{themes.css,tokens.ts}');
